        public var transferId: String

        public init(mime: String? = nil, name: String, sha256: String, size: Int64, target: TransferTarget? = nil, transferId: String) {
            self.mime = mime
            self.name = name
            self.sha256 = sha256
            self.size = size
            self.target = target
            self.transferId = transferId
        }

        enum CodingKeys: String, CodingKey {
            case mime
            case name
            case sha256
            case size
            case target
            case transferId = "transfer_id"
        }
    }

